DROP DATABASE IF EXISTS build3;CREATE DATABASE build3 CHARACTER SET utf8mb4;USE build3;
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(120) UNIQUE,pass VARCHAR(255),title VARCHAR(60),photo VARCHAR(200),last_seen DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(120) UNIQUE,phone VARCHAR(30),pass VARCHAR(255),last_seen DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE requests(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,service VARCHAR(40),details TEXT,budget VARCHAR(40),offer VARCHAR(40) NULL,neg VARCHAR(10) NOT NULL DEFAULT 'client',days INT NULL,file VARCHAR(200) NULL,delivery_url VARCHAR(300) NULL,status ENUM('new','progress','done') DEFAULT 'new',hid TINYINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE chat(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,sender ENUM('client','admin') NOT NULL,admin_id INT NULL,body TEXT,file VARCHAR(200) NULL,seen TINYINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE projects(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120),description TEXT,image VARCHAR(200),url VARCHAR(300),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE project_images(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,image VARCHAR(200),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE comments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,text TEXT,rating TINYINT NOT NULL DEFAULT 0,approved TINYINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE messages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(120),phone VARCHAR(30),body TEXT,is_read TINYINT NOT NULL DEFAULT 0,reply TEXT NULL,replied_at DATETIME NULL,reply_seen TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE attempts(id INT AUTO_INCREMENT PRIMARY KEY,kind VARCHAR(20),k VARCHAR(190),ip VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(kind,k));
CREATE TABLE resets(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,token CHAR(64),expires DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
